 "text": "<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Duskyr</title>
  <!-- LOGO_EVERYWHERE_V1 — значок сайта нигде не был объявлен: браузеры и Google
       брали запасной вариант, поэтому в выдаче висела чужая буква «D». -->
  <link rel="icon" href="/favicon.svg" type="image/svg+xml">
  <link rel="icon" href="/favicon.ico" sizes="48x48">
  <link rel="icon" href="/favicon-192.png" type="image/png" sizes="192x192">
  <link rel="apple-touch-icon" href="/apple-touch-icon.png">
  <meta name="theme-color" content="#0d0e12">
  <script>
    /* Resolve the theme BEFORE first paint so the splash matches the app (no dark<->light flash on load). */
